import re, os
for root, dirs, files in os.walk('src'):
    for f in files:
        p = os.path.join(root, f)
        for i, line in enumerate(open(p, encoding='utf-8'), 1):
            if re.search(r'supersed', line, re.IGNORECASE):
                print(p, i, line.rstrip())

